<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Notification Preferences</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #121a2b;
      --panel-2: #172238;
      --border: #27324a;
      --text: #edf2ff;
      --muted: #9aa8c7;
      --accent: #7c9cff;
      --accent-2: #9b7cff;
      --focus: rgba(124, 156, 255, 0.35);
      --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 38%),
        linear-gradient(180deg, #09101d 0%, #0b1020 100%);
      color: var(--text);
      padding: 24px;
    }

    .app-shell {
      width: min(100%, 560px);
      background: linear-gradient(180deg, rgba(23, 34, 56, 0.92), rgba(18, 26, 43, 0.96));
      border: 1px solid rgba(124, 156, 255, 0.12);
      border-radius: 24px;
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .header {
      padding: 28px 28px 18px;
      border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    }

    .eyebrow {
      margin: 0 0 8px;
      color: var(--accent);
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.5rem, 2vw, 2rem);
      line-height: 1.2;
    }

    .content {
      padding: 28px;
    }

    .form-field {
      padding: 20px;
      background: rgba(255, 255, 255, 0.03);
      border: 1px solid rgba(255, 255, 255, 0.07);
      border-radius: 18px;
    }

    .question {
      margin: 0 0 18px;
      color: var(--text);
      font-size: 1.02rem;
      font-weight: 600;
    }

    .radio-list {
      display: grid;
      gap: 12px;
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .radio-option {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 14px 16px;
      background: rgba(255, 255, 255, 0.02);
      border: 1px solid var(--border);
      border-radius: 14px;
      cursor: pointer;
      transition: transform 0.16s ease, border-color 0.16s ease, background 0.16s ease;
    }

    .radio-option:hover {
      transform: translateY(-1px);
      border-color: rgba(124, 156, 255, 0.35);
      background: rgba(124, 156, 255, 0.06);
    }

    .radio-option input {
      appearance: none;
      width: 18px;
      height: 18px;
      margin: 0;
      border-radius: 50%;
      border: 2px solid #7f8cae;
      display: grid;
      place-items: center;
      flex: 0 0 auto;
      outline: none;
      background: rgba(255, 255, 255, 0.02);
    }

    .radio-option input::before {
      content: "";
      width: 10px;
      height: 10px;
      border-radius: 50%;
      transform: scale(0);
      transition: transform 0.14s ease;
      background: linear-gradient(135deg, var(--accent), var(--accent-2));
    }

    .radio-option input:checked {
      border-color: var(--accent);
      box-shadow: 0 0 0 6px var(--focus);
    }

    .radio-option input:checked::before {
      transform: scale(1);
    }

    .radio-option input:focus-visible {
      box-shadow: 0 0 0 6px var(--focus);
    }

    .radio-label {
      display: grid;
      gap: 3px;
    }

    .radio-label strong {
      font-size: 0.98rem;
      font-weight: 600;
    }

    .radio-label span {
      color: var(--muted);
      font-size: 0.9rem;
    }

    .actions {
      display: flex;
      justify-content: flex-end;
      margin-top: 20px;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 12px;
      padding: 12px 18px;
      color: white;
      font-weight: 700;
      letter-spacing: 0.01em;
      background: linear-gradient(135deg, var(--accent), var(--accent-2));
      box-shadow: 0 12px 30px rgba(124, 156, 255, 0.3);
      cursor: pointer;
      transition: transform 0.16s ease, box-shadow 0.16s ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 16px 34px rgba(124, 156, 255, 0.36);
    }

    button:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    .status {
      margin-top: 16px;
      min-height: 1.25rem;
      color: var(--muted);
      font-size: 0.92rem;
    }

    @media (max-width: 480px) {
      .header,
      .content {
        padding-left: 18px;
        padding-right: 18px;
      }

      .form-field {
        padding: 16px;
      }
    }
  </style>
</head>
<body>
  <main id="root"></main>

  <script>
    function RadioOption({ id, name, value, label, hint }) {
      return `
        <label class="radio-option" for="${id}">
          <input type="radio" id="${id}" name="${name}" value="${value}" required />
          <span class="radio-label">
            <strong>${label}</strong>
            <span>${hint}</span>
          </span>
        </label>
      `;
    }

    function App() {
      return `
        <div class="app-shell">
          <div class="header">
            <p class="eyebrow">Preferences</p>
            <h1>Notification settings</h1>
          </div>
          <div class="content">
            <form id="notification-form">
              <div class="form-field">
                <p class="question">How do you prefer to receive notifications?</p>
                <div class="radio-list" role="radiogroup" aria-labelledby="notification-question">
                  ${RadioOption({
                    id: "notify-email",
                    name: "notification-method",
                    value: "email",
                    label: "Email",
                    hint: "Best for detailed updates and receipts."
                  })}
                  ${RadioOption({
                    id: "notify-sms",
                    name: "notification-method",
                    value: "sms",
                    label: "SMS",
                    hint: "Great for urgent, time-sensitive alerts."
                  })}
                  ${RadioOption({
                    id: "notify-push",
                    name: "notification-method",
                    value: "push",
                    label: "Push Notifications",
                    hint: "Ideal for quick updates on the go."
                  })}
                </div>
              </div>
              <div class="actions">
                <button type="submit">Submit</button>
              </div>
              <div class="status" id="status" aria-live="polite"></div>
            </form>
          </div>
        </div>
      `;
    }

    document.getElementById("root").innerHTML = App();

    const form = document.getElementById("notification-form");
    const status = document.getElementById("status");

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      const selected = new FormData(form).get("notification-method");
      status.textContent = selected
        ? `Saved preference: ${selected === "push" ? "Push Notifications" : selected.charAt(0).toUpperCase() + selected.slice(1)}.`
        : "Please choose a notification method.";
    });
  </script>
</body>
</html>
