      color: var(--muted);
      font-size: 0.9rem;
    }

    .actions {
      display: flex;
      justify-content: flex-end;
      margin-top: 20px;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 12px;
      padding: 12px 18px;
      color: white;
      font-weight: 700;
      letter-spacing: 0.01em;
      background: linear-gradient(135deg, var(--accent), var(--accent-2));
      box-shadow: 0 12px 30px rgba(124, 156, 255, 0.3);
      cursor: pointer;
      transition: transform 0.16s ease, box-shadow 0.16s ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 16px 34px rgba(124, 156, 255, 0.36);
    }

    button:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    .status {
      margin-top: 16px;
      min-height: 1.25rem;
      color: var(--muted);
      font-size: 0.92rem;
    }

    @media (max-width: 480px) {
      .header,
      .content {
        padding-left: 18px;
        padding-right: 18px;
      }

      .form-field {
        padding: 16px;
      }
    }
  </style>
</head>
<body>
  <main id="root"></main>

  <script>
    function RadioOption({ id, name, value, label, hint }) {
      return `
        <label class="radio-option" for="${id}">
          <input type="radio" id="${id}" name="${name}" value="${value}" required />
          <span class="radio-label">
            <strong>${label}</strong>
            <span>${hint}</span>
          </span>
        </label>
      `;
    }

    function App() {
      return `
        <div class="app-shell">
          <div class="header">
            <p class="eyebrow">Preferences</p>
            <h1>Notification settings</h1>
          </div>
          <div class="content">
            <form id="notification-form">
              <div class="form-field">
                <p class="question" id="notification-question">How do you prefer to receive notifications?</p>
                <div class="radio-list" role="radiogroup" aria-labelledby="notification-question">
                  ${RadioOption({
                    id: "notify-email",
                    name: "notification-method",
                    value: "email",
                    label: "Email",
                    hint: "Best for detailed updates and receipts."
                  })}
                  ${RadioOption({
                    id: "notify-sms",
                    name: "notification-method",
                    value: "sms",
                    label: "SMS",
                    hint: "Great for urgent, time-sensitive alerts."
                  })}
                  ${RadioOption({
                    id: "notify-push",
                    name: "notification-method",
                    value: "push",
                    label: "Push Notifications",
                    hint: "Ideal for quick updates on the go."
                  })}
                </div>
              </div>
              <div class="actions">
                <button type="submit">Submit</button>
              </div>
              <div class="status" id="status" aria-live="polite"></div>
            </form>
          </div>
        </div>
      `;
    }

    document.getElementById("root").innerHTML = App();

    const form = document.getElementById("notification-form");
    const status = document.getElementById("status");

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      const selected = new FormData(form).get("notification-method");
      status.textContent = selected
        ? `Saved preference: ${selected === "push" ? "Push Notifications" : selected.charAt(0).toUpperCase() + selected.slice(1)}.`
        : "Please choose a notification method.";
    });
  </script>
</body>
</html>
